<?php use App\Core\Db; $pdo=Db::pdo(); $type=isset($_GET['type'])?$_GET['type']:'proposal'; $g=$m=array();$vp=$ceo=null; if($pdo){$g=$pdo->query("SELECT id,name FROM employees WHERE is_active=1 AND department='공무'")->fetchAll();$m=$pdo->query("SELECT id,name FROM employees WHERE is_active=1 AND department='관리'")->fetchAll();$vp=$pdo->query("SELECT id,name FROM employees WHERE is_active=1 AND position='부사장' LIMIT 1")->fetch();$ceo=$pdo->query("SELECT id,name FROM employees WHERE is_active=1 AND position IN ('대표','대표이사') LIMIT 1")->fetch();} $missing=(!$vp||!$ceo); ?>
<div class="bg-white rounded-2xl p-6 border"><h2>작성</h2><?php if($missing):?><div>직원명부에서 부사장 또는 대표가 등록되어 있지 않습니다. 관리 메뉴에서 먼저 등록해주세요.</div><?php endif;?><form method="post" action="?r=approval_store"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><input type="hidden" name="doc_type" value="<?php echo h($type);?>"><input name="title" required><textarea name="content"></textarea><select name="gongmu_id"><?php foreach($g as $e):?><option value="<?php echo $e['id'];?>"><?php echo h($e['name']);?></option><?php endforeach;?></select><select name="manage_id"><?php foreach($m as $e):?><option value="<?php echo $e['id'];?>"><?php echo h($e['name']);?></option><?php endforeach;?></select><button <?php echo $missing?'disabled':'';?>>저장</button></form></div>